update public.career_jobs
set role_details=jsonb_set(jsonb_set(jsonb_set(coalesce(role_details,'{}'::jsonb),'{systemRole}','"developer"'::jsonb,true),'{department}','"Development"'::jsonb,true),'{trainingTrack}','"web_development"'::jsonb,true),
    application_type='general',application_url='/careers/web-developer/apply',application_cta='Apply for Web Developer',requires_intro_video=false,updated_at=now()
where slug='web-developer';

with j as (select id from public.career_jobs where slug='web-developer' limit 1),
p(stage,sort_order,assessment_required,passing_score,sla_hours,interview_required,rubric) as (
values
('New Application',1,false,null::integer,24,false,'[]'::jsonb),
