('Technical Assessment',4,true,80,72,false,'[{"key":"fundamentals","label":"Web/platform fundamentals","maxPoints":20},{"key":"architecture","label":"Implementation and architecture judgment","maxPoints":20},{"key":"debugging","label":"Debugging/problem decomposition","maxPoints":15},{"key":"testing","label":"Testing and regression strategy","maxPoints":15},{"key":"security","label":"Security/data-handling judgment","maxPoints":15},{"key":"performanceAccessibility","label":"Performance and accessibility reasoning","maxPoints":15}]'::jsonb),
('Development Practical',5,true,80,96,false,'[{"key":"fidelity","label":"Accurate implementation against supplied design/requirements","maxPoints":20},{"key":"responsive","label":"Responsive behavior and interaction states","maxPoints":15},{"key":"reuse","label":"Component reuse and maintainable structure","maxPoints":15},{"key":"git","label":"Branch/commit/PR discipline","maxPoints":15},{"key":"testing","label":"Testing and defect handling","maxPoints":15},{"key":"quality","label":"Accessibility/performance/security baseline","maxPoints":15},{"key":"handoff","label":"README/release evidence and handoff clarity","maxPoints":5}]'::jsonb),
