('Selected',7,false,null::integer,24,false,'[]'::jsonb),('Agreement Pending',8,false,null::integer,72,false,'[]'::jsonb),('Developer Academy',9,false,null::integer,168,false,'[]'::jsonb),('Final Approval',10,false,null::integer,24,false,'[]'::jsonb),('Ready for System Access',11,false,null::integer,24,false,'[]'::jsonb),('Activated',12,false,null::integer,0,false,'[]'::jsonb)
